package ama.api;
import ama.contract.IdentityContracts.*;import ama.transcript.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Actual controller route/parser; mocked receipt boundary deliberately avoids database/factory work. */
class Task11PublicationRetryTest {
 static final String MEETING="12345678-1234-4234-8234-123456789abc",PUB="12345678-1234-4234-8234-123456789abd",OP="PUBLICATION_ZERO_EFFECT_RETRY";
 final JdbcPublicationQueries queries=mock(JdbcPublicationQueries.class);final List<List<String>> semantics=new ArrayList<>();
 final MinutesConfiguration.Runtime runtime=new MinutesConfiguration.Runtime(null,null,null,null,null,null,null,null,65536);
 final ResolvedSession session=new ResolvedSession(new Actor("owner",Status.ACTIVE,Set.of(Role.USER)),"T".repeat(43),Instant.now().plusSeconds(60));
 MockMvc mvc(){return MockMvcBuilders.standaloneSetup(new PublicationController(runtime,mock(ama.db.TransactionRunner.class),mock(ama.access.MeetingAccess.class),queries)).setControllerAdvice(new PublicationErrors()).build();}
 void receipt(){doAnswer(call->{semantics.add(List.of((String[])call.getRawArguments()[4]));return Optional.of(Map.of("taskId","original-task","executionId","original-execution","replayed",true));}).when(queries).lookup(any(),eq(MEETING),eq(OP),eq("retry-key"),any(String[].class));}
 org.springframework.mock.web.MockHttpServletResponse request(byte[] body,String... keys)throws Exception {var r=post("/api/v1/meetings/"+MEETING+"/publications/"+PUB+"/zero-effect-retries").requestAttr(SessionSecurityFilter.SESSION,session).contentType("application/json").content(body);for(String key:keys)r.header("Idempotency-Key",key);return mvc().perform(r).andReturn().getResponse();}
 String body(String counter,String form){StringBuilder b=new StringBuilder("{");for(String field:List.of("expectedRevision","expectedPublicationRevision","expectedExecutionNo")){if(b.length()>1)b.append(',');if(!form.equals("token"))b.append('"').append(field).append("\":").append(counter);if(form.equals("dual"))b.append(',');if(!form.equals("integer"))b.append('"').append(field).append("Token\":\"").append(counter).append('"');}return b.append('}').toString();}
 @Test void losslessThreeCounterFormsReplayBeforeUnavailableFactory()throws Exception {receipt();for(String n:List.of("9007199254740991","9007199254740992","9007199254740993","9223372036854775806"))for(String form:List.of("integer","token","dual")){var r=request(body(n,form).getBytes(java.nio.charset.StandardCharsets.UTF_8),"retry-key");assertEquals(202,r.getStatus(),r.getContentAsString());assertEquals("private, no-store",r.getHeader("Cache-Control"));assertTrue(r.getContentAsString().contains("original-execution"));assertEquals(List.of(PUB,n,n,n),semantics.getLast());}}
 @Test void malformedCountersAndNonCounterFieldsNeverReachReceiptOrFactory()throws Exception {for(String invalid:List.of("{", "[]",body("1","token")+"{}","{\"expectedRevisionToken\":\"1\",\"expectedRevisionToken\":\"1\"}","{\"expectedRevisionToken\":\"1\",\"expectedPublicationRevisionToken\":\"1\",\"expectedExecutionNoToken\":\"0\"}",body("1","token").replace("\"1\"","\"01\""),body("1","token").replace("\"1\"","\"١\""),body("1","token").replace("\"1\"","\"+1\""),body("1","token").replace("\"1\"","null"),body("1","integer").replace(":1",":-1"),body("1","integer").replace(":1",":1e0"),body("1","integer").replace(":1",":1.0"),body("1","integer").replace(":1",":01"),body("1","dual").replace("expectedRevisionToken\":\"1","expectedRevisionToken\":\"2"),body("9223372036854775807","token"),body("1","token").replace("}",",\"confirmationId\":\""+PUB+"\"}"))){var r=request(invalid.getBytes(java.nio.charset.StandardCharsets.UTF_8),"retry-key");assertEquals(400,r.getStatus(),invalid+" -> "+r.getContentAsString());assertEquals("private, no-store",r.getHeader("Cache-Control"));}verifyNoInteractions(queries);}
 @Test void invalidUtf8IsRejectedWithoutDispatch()throws Exception {byte[] data=body("1","token").getBytes(java.nio.charset.StandardCharsets.UTF_8);for(int i=0;i<data.length;i++)if(data[i]=='1'){data[i]=(byte)0xff;break;}assertEquals(400,request(data,"retry-key").getStatus());verifyNoInteractions(queries);}
 @Test void boundedBodyAndExactlyOneIdempotencyKey()throws Exception {assertEquals(413,request(new byte[65537],"retry-key").getStatus());for(String[] keys:List.of(new String[]{},new String[]{"retry-key","retry-key"},new String[]{""})){assertEquals(400,request(body("1","token").getBytes(java.nio.charset.StandardCharsets.UTF_8),keys).getStatus());}verifyNoInteractions(queries);}
 @Test void freshAuthorizationDenialDoesNotFallThroughToNewCommand()throws Exception {when(queries.lookup(any(),eq(MEETING),eq(OP),eq("retry-key"),any(String[].class))).thenThrow(new ama.access.MeetingAccess.AccessDeniedException());var r=request(body("1","token").getBytes(java.nio.charset.StandardCharsets.UTF_8),"retry-key");assertEquals(403,r.getStatus());assertEquals("private, no-store",r.getHeader("Cache-Control"));}
 @Test void genuineReceiptMissUsesExplicitUnavailableResponse()throws Exception {when(queries.lookup(any(),anyString(),anyString(),anyString(),any(String[].class))).thenReturn(Optional.empty());var r=request(body("1","token").getBytes(java.nio.charset.StandardCharsets.UTF_8),"retry-key");assertEquals(503,r.getStatus());assertTrue(r.getContentAsString().contains("PUBLICATION_NOT_INSTALLED"));assertEquals("private, no-store",r.getHeader("Cache-Control"));}
 @Test void validMissDispatchesOnlyNormalizedFixedCounterRequest()throws Exception {when(queries.lookup(any(),anyString(),anyString(),anyString(),any(String[].class))).thenReturn(Optional.empty());var calls=new ArrayList<List<Object>>();var service=mock(JdbcPublicationService.class,invocation->{if(invocation.getMethod().getName().equals("retryZeroEffect")){calls.add(Arrays.asList(invocation.getArguments()));return Map.of("taskId","accepted-task");}return org.mockito.Answers.RETURNS_DEFAULTS.answer(invocation);});var installed=new MinutesConfiguration.Runtime(null,null,null,null,null,null,service,null,65536);var mvc=MockMvcBuilders.standaloneSetup(new PublicationController(installed,null,null,queries)).setControllerAdvice(new PublicationErrors()).build();var r=mvc.perform(post("/api/v1/meetings/"+MEETING+"/publications/"+PUB+"/zero-effect-retries").requestAttr(SessionSecurityFilter.SESSION,session).header("Idempotency-Key","retry-key").contentType("application/json").content(body("9007199254740993","dual"))).andReturn().getResponse();assertEquals(202,r.getStatus(),r.getContentAsString());assertEquals("private, no-store",r.getHeader("Cache-Control"));assertEquals(1,calls.size());assertEquals(List.of(session.actor(),MEETING,PUB,"retry-key",9007199254740993L,9007199254740993L,9007199254740993L),calls.getFirst().subList(0,7));}
}
